INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "李茂贞", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“岐王在唐亡后开府置百官”中为开府者。", "biography": null, "status": "draft", "id": "af9a00d1-c748-5b5f-9175-1af19530d83d"}, {"name": "苻昭", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷266开平元年条所见人物：苻昭。", "biography": null, "status": "draft", "id": "15eeb875-6864-5303-a718-b8a0991ac017"}, {"name": "阿保机", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷266开平元年条所见人物：阿保机。", "biography": null, "status": "draft", "id": "c632d829-b418-5526-94fd-cc14fddaa9bd"}, {"name": "李克用", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": 908, "description": "河东晋王，李存勖之父。908年去世，临终命李存勖继承军府。此处的晋不等于后来的后晋。", "biography": "河东晋王，李存勖之父。908年去世，临终命李存勖继承军府。此处的晋不等于后来的后晋。", "status": "draft", "id": "04af206e-fa86-581c-86b9-87a78a8d59a5"}]'::jsonb)
