INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "李克用复用张承业为监军", "start_year": 907, "end_year": 907, "time_original": "907年后梁建立后条，具体日期未载", "dynasty": "唐末五代十国", "description": "李克用重新任用张承业为监军。段首保护张承业之事属于唐末追叙，不定为907年新事件。", "phases": [], "location_name": "河东", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "历史地名与今地的对应尚待考证。", "status": "draft", "id": "ff7d2895-af9b-5e1a-9e58-408db8f80d80"}, {"title": "岐王亲往苻昭家应对告反", "start_year": null, "end_year": null, "time_original": "唐末追叙；确年未载", "dynasty": "唐", "description": "岐王亲往苻昭家应对告反。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "daed7c84-51de-5204-89c0-875aeb70fcd6"}, {"title": "岐王在唐亡后开府置百官", "start_year": 907, "end_year": 907, "time_original": "907年闻唐亡后，具体日期未载", "dynasty": "唐末五代十国", "description": "岐王在唐亡后没有称帝，但开府置百官，多项礼仪仿照帝制。段首有关治军的轶事不强行断为本年。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "具体地点未详。", "status": "draft", "id": "a611cfa4-e1e8-5520-879a-d4dddf826ae0"}, {"title": "罗隐劝钱镠讨梁，钱镠未采纳", "start_year": 907, "end_year": 907, "time_original": "907年后梁建立后条，具体日期未载", "dynasty": "唐末五代十国", "description": "罗隐劝钱镠出兵讨梁；原文记钱镠未能采用该建议。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "具体地点未详。", "status": "draft", "id": "691b6d3c-a4ad-5313-b477-bfd3fe435a30"}, {"title": "薛贻矩出任中书侍郎、同平章事", "start_year": 907, "end_year": 907, "time_original": "梁开平元年五月丁丑朔", "dynasty": "唐末五代十国", "description": "后梁以薛贻矩为中书侍郎、同平章事。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "具体地点未详。", "status": "draft", "id": "7f037028-1cb0-540b-8a42-3fc2671273b7"}, {"title": "后梁加授王镕、罗绍威、王处直官衔", "start_year": 907, "end_year": 907, "time_original": "梁开平元年五月条，具体日未载", "dynasty": "唐末五代十国", "description": "后梁加授王镕、罗绍威、王处直官衔。所据文本“王镕宁太师”有疑字，具体官衔待考。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "具体地点未详。", "status": "draft", "id": "9d9135d7-89d5-5d3a-94cf-cb1b7d60cfeb"}, {"title": "阿保机逐渐兼并契丹诸部并向外扩张", "start_year": null, "end_year": null, "time_original": "907年以前的追叙；确年未载", "dynasty": "唐", "description": "阿保机逐渐兼并契丹诸部并向外扩张。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "e5e47b25-33df-5458-9360-00d211dc0248"}, {"title": "契丹与后梁互遣使者通好", "start_year": 907, "end_year": 907, "time_original": "907年后梁建立后（通鉴系五月条，新五代史系四月条）", "dynasty": "唐末五代十国", "description": "契丹遣袍笏梅老通好，后梁遣高颀回访。契丹沿革及此前会盟不属于此次使行。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "具体地点未详。", "status": "draft", "id": "e0b379cb-4573-54fd-899c-5b100698019d"}, {"title": "阿保机与晋王李克用在云州东城会盟", "start_year": 907, "end_year": 907, "time_original": "907年；约当年冬共击梁", "dynasty": "唐", "description": "阿保机与晋王李克用在云州东城会盟。", "phases": [], "location_name": "云州东城", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "86846ae4-a8c6-5a29-85a5-c7eae6486902"}, {"title": "阿保机归后背弃晋王之盟而附梁", "start_year": 907, "end_year": 907, "time_original": "907年会盟后；确日未载", "dynasty": "唐", "description": "阿保机归后背弃晋王之盟而附梁。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "4e9961b4-1d29-55aa-857b-36cfad4ea030"}, {"title": "后梁加封钱镠、张全义、刘隐等", "start_year": 907, "end_year": 907, "time_original": "梁开平元年五月己卯", "dynasty": "唐末五代十国", "description": "后梁封张全义为魏王、钱镠为吴越王；加刘隐、王审知兼侍中，封刘隐为大彭王。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "具体地点未详。", "status": "draft", "id": "ba18f771-e163-5b40-837f-ffbd572978b9"}, {"title": "高季昌受命为荆南节度使", "start_year": 907, "end_year": 907, "time_original": "梁开平元年五月癸未", "dynasty": "唐末五代十国", "description": "后梁以高季昌为荆南节度使；原文记其到任后安集流散人口。江陵的恢复并非一日完成。", "phases": [], "location_name": "荆南、江陵", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "历史地名与今地的对应尚待考证。", "status": "draft", "id": "727305cf-fa90-5394-b0ce-23c8c9000212"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

