INSERT INTO public.fact_claim (id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status)
SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "晋王复任张承业为监军。", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p023·原文件第28行", "note": "原文：至是，复以为监军，待之加厚，承业亦为之竭力。；核对说明：前句斛律寺匿人属于唐末追叙；本句为复任。", "status": "draft", "id": "d3c80ca6-8338-5329-9611-b0d7e4cdf0e1", "subject_id": "ff7d2895-af9b-5e1a-9e58-408db8f80d80", "source_id": "4897452e-4b88-543d-b373-6c4118b90ab3"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "907年本段条；确日未载", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p023·原文件第28行", "note": "原文：至是，复以为监军，待之加厚，承业亦为之竭力。；核对说明：前句斛律寺匿人属于唐末追叙；本句为复任。", "status": "draft", "id": "ee113fc9-c1c6-5b5e-a5bd-fa71c763aee5", "subject_id": "ff7d2895-af9b-5e1a-9e58-408db8f80d80", "source_id": "4897452e-4b88-543d-b373-6c4118b90ab3"}, {"subject_table": "event", "field_path": "description", "claim_text": "唐末李克用将张承业藏于斛律寺，以免被诛。", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p023·原文件第28行", "note": "原文：晋王匿监军张承业于斛律寺，斩罪人以应诏。；核对说明：追叙发生时间未在此段确载；不作为907年新事。", "status": "draft", "id": "44a1c38a-6065-51f0-9e19-f60d303060ff", "subject_id": "ff7d2895-af9b-5e1a-9e58-408db8f80d80", "source_id": "4897452e-4b88-543d-b373-6c4118b90ab3"}, {"subject_table": "event", "field_path": "description", "claim_text": "《新五代史》卷三十八亦记李克用藏张承业于斛律寺，后复用为监军。", "citation": "《新五代史》卷三十八，段落 xin-wudaishi-b08f244b9241-p001328；EPUB电子本，纸本及异文待核", "note": "原文：晉王憐承業，不忍殺，匿之斛律寺。昭宗崩，乃出承業，復為監軍。；核对说明：新史将复任系于昭宗死后；与主书“至是”的叙述时间不同，保留两书写法。", "status": "draft", "id": "ac95f14d-6905-5c55-b07f-9c7c780a24cc", "subject_id": "ff7d2895-af9b-5e1a-9e58-408db8f80d80", "source_id": "51459ff9-76dd-5e80-91fd-e36108d23098"}, {"subject_table": "event", "field_path": "description", "claim_text": "岐王亲往苻昭家应对告反。", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p024·原文件第29行", "note": "原文：有告部将苻昭反者，岐王直诣其家，悉去左右，熟寝经宿而还；由是众心悦服。；核对说明：此为治军轶事，无明确年份；不将“告反”确认为苻昭真的谋反。", "status": "draft", "id": "a8f50a3a-9df0-5b7e-a2ae-d57ca30c3c94", "subject_id": "daed7c84-51de-5204-89c0-875aeb70fcd6", "source_id": "4897452e-4b88-543d-b373-6c4118b90ab3"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "唐末追叙；确年未载", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p024·原文件第29行", "note": "原文：有告部将苻昭反者，岐王直诣其家，悉去左右，熟寝经宿而还；由是众心悦服。；核对说明：此为治军轶事，无明确年份；不将“告反”确认为苻昭真的谋反。", "status": "draft", "id": "5d00225f-6bd0-58f3-b809-06eeb58345f7", "subject_id": "daed7c84-51de-5204-89c0-875aeb70fcd6", "source_id": "4897452e-4b88-543d-b373-6c4118b90ab3"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记李茂贞：被告反后亲赴苻昭家的岐王。", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p024·原文件第29行", "note": "原文：有告部将苻昭反者，岐王直诣其家，悉去左右，熟寝经宿而还；由是众心悦服。；核对说明：只据本段确认参与身份；同名与异体字回查后复用。", "status": "draft", "id": "42579c6f-3e72-52fa-b085-75071d092f14", "subject_id": "af9a00d1-c748-5b5f-9175-1af19530d83d", "source_id": "4897452e-4b88-543d-b373-6c4118b90ab3"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "李茂贞：被告反后亲赴苻昭家的岐王。", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p024·原文件第29行", "note": "原文：有告部将苻昭反者，岐王直诣其家，悉去左右，熟寝经宿而还；由是众心悦服。；核对说明：参与身份依据本段措辞，不因同场出现推定额外关系。", "status": "draft", "id": "442d9591-a69f-5c7a-a45b-64c0b346c2c2", "subject_id": "1f06f0fb-84fe-5514-8eab-fedfcf2637a2", "source_id": "4897452e-4b88-543d-b373-6c4118b90ab3"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记苻昭：被人告发谋反的部将。", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p024·原文件第29行", "note": "原文：有告部将苻昭反者，岐王直诣其家，悉去左右，熟寝经宿而还；由是众心悦服。；核对说明：只据本段确认参与身份；同名与异体字回查后复用。", "status": "draft", "id": "08401afe-7471-53ba-8d36-02f1e56cca32", "subject_id": "15eeb875-6864-5303-a718-b8a0991ac017", "source_id": "4897452e-4b88-543d-b373-6c4118b90ab3"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "苻昭：被人告发谋反的部将。", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p024·原文件第29行", "note": "原文：有告部将苻昭反者，岐王直诣其家，悉去左右，熟寝经宿而还；由是众心悦服。；核对说明：参与身份依据本段措辞，不因同场出现推定额外关系。", "status": "draft", "id": "b30d249b-3650-56bb-b01a-e35aaa7084e0", "subject_id": "bfa340ce-d4b1-5c90-b8e6-0a28c88fb9a7", "source_id": "4897452e-4b88-543d-b373-6c4118b90ab3"}, {"subject_table": "event", "field_path": "description", "claim_text": "岐王在唐亡后开王府置百官而未称帝。", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p024·原文件第29行", "note": "原文：及闻唐亡，以兵羸地蹙，不敢称帝，但开岐王府，置百官，名其所居为宫殿，妻称皇后，将吏上书称笺表，鞭、扇、号令多拟帝者。；核对说明：开府和拟帝仪制不等于正式称帝；原文明确“不敢称帝”。", "status": "draft", "id": "fe7fb01a-727c-5e10-b154-c93d0113b84d", "subject_id": "a611cfa4-e1e8-5520-879a-d4dddf826ae0", "source_id": "4897452e-4b88-543d-b373-6c4118b90ab3"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "907年唐亡后；确日未载", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p024·原文件第29行", "note": "原文：及闻唐亡，以兵羸地蹙，不敢称帝，但开岐王府，置百官，名其所居为宫殿，妻称皇后，将吏上书称笺表，鞭、扇、号令多拟帝者。；核对说明：开府和拟帝仪制不等于正式称帝；原文明确“不敢称帝”。", "status": "draft", "id": "6864ed70-5b70-51b1-a614-72c5c386971d", "subject_id": "a611cfa4-e1e8-5520-879a-d4dddf826ae0", "source_id": "4897452e-4b88-543d-b373-6c4118b90ab3"}, {"subject_table": "event", "field_path": "description", "claim_text": "罗隐劝钱镠兴兵讨梁，钱镠未采纳。", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p025·原文件第30行", "note": "原文：镇海节度判官罗隐说吴王镠兴兵讨梁；核对说明：“虽不能用”明确是未采纳；不推定钱镠实际出兵。", "status": "draft", "id": "c5954ea9-2f61-5010-ac86-2604d0a43251", "subject_id": "691b6d3c-a4ad-5313-b477-bfd3fe435a30", "source_id": "4897452e-4b88-543d-b373-6c4118b90ab3"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "907年唐亡后；确日未载", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p025·原文件第30行", "note": "原文：镇海节度判官罗隐说吴王镠兴兵讨梁；核对说明：“虽不能用”明确是未采纳；不推定钱镠实际出兵。", "status": "draft", "id": "656b816c-619c-5ff8-9931-37568913510a", "subject_id": "691b6d3c-a4ad-5313-b477-bfd3fe435a30", "source_id": "4897452e-4b88-543d-b373-6c4118b90ab3"}, {"subject_table": "event", "field_path": "description", "claim_text": "钱镠虽未采用罗隐建议，仍赞许其态度。", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p025·原文件第30行", "note": "原文：虽不能用，心甚义之。；核对说明：仅记录主书对钱镠态度的叙述。", "status": "draft", "id": "c0f8bf48-f030-5787-8748-ed9e21c71cb5", "subject_id": "691b6d3c-a4ad-5313-b477-bfd3fe435a30", "source_id": "4897452e-4b88-543d-b373-6c4118b90ab3"}, {"subject_table": "event", "field_path": "description", "claim_text": "薛贻矩任中书侍郎、同平章事。", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p026·原文件第31行", "note": "原文：五月，丁丑朔，以御史大夫薛贻矩为中书侍郎、同平章事。；核对说明：按主书干支纪日，不自行换算公历。", "status": "draft", "id": "28a5a2cd-5226-5a4a-a884-4ecd63cf11c1", "subject_id": "7f037028-1cb0-540b-8a42-3fc2671273b7", "source_id": "4897452e-4b88-543d-b373-6c4118b90ab3"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "907年五月丁丑朔", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p026·原文件第31行", "note": "原文：五月，丁丑朔，以御史大夫薛贻矩为中书侍郎、同平章事。；核对说明：按主书干支纪日，不自行换算公历。", "status": "draft", "id": "f4c14db3-3095-5d09-bbe5-84277604aeb4", "subject_id": "7f037028-1cb0-540b-8a42-3fc2671273b7", "source_id": "4897452e-4b88-543d-b373-6c4118b90ab3"}, {"subject_table": "event", "field_path": "description", "claim_text": "后梁加授王镕、罗绍威、王处直官衔。", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p027·原文件第32行", "note": "原文：加武顺军节度使赵王王镕宁太师，天雄节度使鄴王罗绍威守太傅，义武节度使王处直兼侍中。；核对说明：电子底本“王镕宁太师”疑有讹字，原文照录；不确认具体官衔。", "status": "draft", "id": "5416678e-76d8-581f-a40d-66923ae814ad", "subject_id": "9d9135d7-89d5-5d3a-94cf-cb1b7d60cfeb", "source_id": "4897452e-4b88-543d-b373-6c4118b90ab3"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "907年五月丁丑朔后；确日未载", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p027·原文件第32行", "note": "原文：加武顺军节度使赵王王镕宁太师，天雄节度使鄴王罗绍威守太傅，义武节度使王处直兼侍中。；核对说明：电子底本“王镕宁太师”疑有讹字，原文照录；不确认具体官衔。", "status": "draft", "id": "99fc12c0-2a20-585f-b0a7-0531062b8948", "subject_id": "9d9135d7-89d5-5d3a-94cf-cb1b7d60cfeb", "source_id": "4897452e-4b88-543d-b373-6c4118b90ab3"}, {"subject_table": "event", "field_path": "description", "claim_text": "阿保机逐渐兼并契丹诸部并向外扩张。", "citation": "卷266·开平元年（907）·zztj-v266-y0907-p028·原文件第33行", "note": "原文：其后阿保机稍以兵击灭七部，复并为一国。又北侵室韦、女真，西取突阙故地，击奚，灭之，复立奚王而使契丹监其兵，东北诸夷皆畏服之。；核对说明：“其后”“稍”表示持续过程；不把所有征服定于907年。", "s